    if (Date.parse(now) >= Date.parse(c.expires_at)) { out.expire.push(c); continue; }
    if (age >= cfg.nudgeAfterDays && !c.nudged_at) out.nudge.push(c);
    if (age >= cfg.escalateAfterDays && !c.escalated_at) out.escalate.push(c);
  }
  return out;
}

